// sin restricted to its principal domain [-π/2, π/2]
const hp = Math.PI / 2;
const sinPts = [];
for (let i = 0; i <= 80; i++) { const x = -hp + (2 * hp) * i / 80; sinPts.push([x, Math.sin(x)]); }
v.path(sinPts, { color: H.colors.accent, width: 2.6 });
// arcsin = reflection of that branch across y = x
const asinPts = [];
for (let i = 0; i <= 80; i++) { const x = -1 + 2 * i / 80; asinPts.push([x, Math.asin(x)]); }
v.path(asinPts, { color: H.colors.accent2, width: 2.6 });
// the inverse pairing: (xq, arcsin xq) on the orange curve, mirror (arcsin xq, xq) on blue
